package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"net/url"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type OAuthConfig struct {
	ClientID     string
	ClientSecret string
	AuthorizeURL string
}

var oauthCfg = OAuthConfig{
	ClientID:     "app-client-id-29f8a",
	ClientSecret: "secret-key-here",
	AuthorizeURL: "https://auth.provider.example.com/authorize",
}

func init() {
	var err error
	db, err = sql.Open("postgres", "host=pgbouncer port=6432 dbname=appdb sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// registerRedirectURI stores allowed redirect URIs per client
func registerRedirectURI(w http.ResponseWriter, r *http.Request) {
	clientID := r.FormValue("client_id")
	redirectURI := r.FormValue("redirect_uri")

	// Uses parameterized query via pgBouncer prepared statement mode
	_, err := db.Exec("INSERT INTO allowed_redirects (client_id, uri) VALUES ($1, $2)", clientID, redirectURI)
	if err != nil {
		http.Error(w, "Failed to register", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

// validateRedirectURI checks if the redirect_uri is registered
func validateRedirectURI(clientID, redirectURI string) (bool, error) {
	var count int
	// Parameterized query - safe from SQL injection
	err := db.QueryRow("SELECT COUNT(*) FROM allowed_redirects WHERE client_id = $1 AND uri = $2", clientID, redirectURI).Scan(&count)
	if err != nil {
		return false, err
	}
	return count > 0, nil
}

// authorizeHandler handles OAuth authorization requests
func authorizeHandler(w http.ResponseWriter, r *http.Request) {
	clientID := r.URL.Query().Get("client_id")
	redirectURI := r.URL.Query().Get("redirect_uri")
	state := r.URL.Query().Get("state")
	scope := r.URL.Query().Get("scope")

	if clientID == "" || redirectURI == "" {
		http.Error(w, "Missing required parameters", http.StatusBadRequest)
		return
	}

	// Parse the redirect URI to validate it
	parsed, err := url.Parse(redirectURI)
	if err != nil {
		http.Error(w, "Invalid redirect_uri", http.StatusBadRequest)
		return
	}

	// VULNERABILITY: Only checks the host portion after parsing
	// An attacker can use backslash tricks or authority confusion
	// e.g., redirect_uri=https://legit.example.com\@evil.com/callback
	// url.Parse in Go treats this differently than browsers
	normalizedURI := fmt.Sprintf("%s://%s%s", parsed.Scheme, parsed.Host, parsed.Path)

	// Check against database of allowed URIs
	valid, err := validateRedirectURI(clientID, normalizedURI)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	if !valid {
		// Fallback: prefix match against registered domains
		var registeredURI string
		err = db.QueryRow("SELECT uri FROM allowed_redirects WHERE client_id = $1 LIMIT 1", clientID).Scan(&registeredURI)
		if err != nil {
			http.Error(w, "Unknown client", http.StatusBadRequest)
			return
		}
		// VULNERABILITY: Weak prefix check allows subdomain bypass
		// If registered is "https://app.example.com", attacker uses
		// "https://app.example.com.evil.com/callback"
		if !strings.HasPrefix(redirectURI, registeredURI) {
			http.Error(w, "redirect_uri not allowed", http.StatusForbidden)
			return
		}
	}

	// Generate authorization code and redirect
	code := generateAuthCode(clientID, scope)

	// Store code mapping
	_, _ = db.Exec("INSERT INTO auth_codes (code, client_id, redirect_uri, scope) VALUES ($1, $2, $3, $4)",
		code, clientID, redirectURI, scope)

	// Redirect user to the (potentially attacker-controlled) URI
	finalURL := fmt.Sprintf("%s?code=%s&state=%s", redirectURI, code, state)
	http.Redirect(w, r, finalURL, http.StatusFound)
}

func generateAuthCode(clientID, scope string) string {
	return fmt.Sprintf("authcode_%s_%s_random123", clientID, scope)
}

func tokenHandler(w http.ResponseWriter, r *http.Request) {
	code := r.FormValue("code")
	redirectURI := r.FormValue("redirect_uri")

	var storedURI string
	err := db.QueryRow("SELECT redirect_uri FROM auth_codes WHERE code = $1", code).Scan(&storedURI)
	if err != nil {
		http.Error(w, "Invalid code", http.StatusBadRequest)
		return
	}

	if storedURI != redirectURI {
		http.Error(w, "redirect_uri mismatch", http.StatusBadRequest)
		return
	}

	token := map[string]string{"access_token": "tok_live_abc123", "token_type": "bearer"}
	json.NewEncoder(w).Encode(token)
}

func main() {
	http.HandleFunc("/oauth/authorize", authorizeHandler)
	http.HandleFunc("/oauth/token", tokenHandler)
	http.HandleFunc("/admin/register-redirect", registerRedirectURI)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
